import { pino } from 'pino'

export const logger = pino({ name: 'frame-inventory-bff' })
import { ApolloServer } from '@apollo/server'
import { loadFilesSync } from '@graphql-tools/load-files'
import type { DocumentNode } from 'graphql'
import { join } from 'node:path'
import type { FrameClient } from './frame-client'
import { logger } from './logger'
import type { RequestContext } from './request-context'
import { createFrameResolvers } from './resolvers/frames'
import { sentryPlugin } from './sentry'

export function createServer(client: FrameClient) {
  const typeDefs = loadFilesSync<DocumentNode>(join(__dirname, '../schema'), {
    extensions: ['gql'],
  })

  return new ApolloServer<RequestContext>({
    typeDefs,
    logger,
    plugins: [
      sentryPlugin,
      {
        async serverWillStart() {
          return {
            async serverWillStop() {
              client.close()
            },
          }
        },
      },
    ],
    includeStacktraceInErrorResponses: false,
    resolvers: createFrameResolvers(client),
  })
}
export interface RequestContext {
  correlationId?: string
}
import type { ApolloServerPlugin } from '@apollo/server'
import * as Sentry from '@sentry/node'
import { GRAPHQL_ERROR_CODES } from './consts'

const dsn = process.env.SENTRY_DSN
if (dsn) {
  Sentry.init({
    dsn,
    beforeSend(event) {
      delete event.request
      delete event.breadcrumbs
      return event
    },
  })
}

export const sentryPlugin: ApolloServerPlugin = {
  async requestDidStart() {
    return {
      async didEncounterErrors({ errors }) {
        for (const error of errors) {
          const code = error.extensions.code
          if (
            code === GRAPHQL_ERROR_CODES.INTERNAL_SERVER_ERROR ||
            code === GRAPHQL_ERROR_CODES.SERVICE_UNAVAILABLE ||
            (code === undefined && error.path)
          ) {
            Sentry.captureException(error.originalError ?? error)
          }
        }
      },
    }
  },
  async unexpectedErrorProcessingRequest({ error }) {
    Sentry.captureException(error)
  },
}
