package com.global.ct.frameinventory.common.grpc;

import java.util.UUID;
import java.util.function.Supplier;
import java.util.regex.Pattern;

import io.grpc.ForwardingServerCallListener;
import io.grpc.Metadata;
import io.grpc.ServerCall;
import io.grpc.ServerCallHandler;
import io.grpc.ServerInterceptor;
import org.slf4j.MDC;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.grpc.server.GlobalServerInterceptor;
import org.springframework.stereotype.Component;

@Component
@GlobalServerInterceptor
@Order(Ordered.HIGHEST_PRECEDENCE)
public class CorrelationIdInterceptor implements ServerInterceptor {
    private static final Metadata.Key<String> HEADER =
            Metadata.Key.of("x-correlation-id", Metadata.ASCII_STRING_MARSHALLER);
    private static final Pattern UUID_PATTERN =
Pattern.compile("[A-Fa-f0-9]{8}(-[A-Fa-f0-9]{4}){3}-[A-Fa-f0-9]{12}");
    private static final String LOG_FIELD = "correlationId";

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        String suppliedId = headers.get(HEADER);
        String correlationId = suppliedId != null && UUID_PATTERN.matcher(suppliedId).matches()
                ? suppliedId : UUID.randomUUID().toString();
        var listener = withCorrelationId(correlationId, () -> next.startCall(call, headers));

        return new ForwardingServerCallListener.SimpleForwardingServerCallListener<>(listener) {
            @Override
            public void onHalfClose() {
                withCorrelationId(correlationId, () -> {
                    super.onHalfClose();
                    return null;
                });
            }
        };
    }

    private static <T> T withCorrelationId(String correlationId, Supplier<T> action) {
        String previous = MDC.get(LOG_FIELD);
        MDC.put(LOG_FIELD, correlationId);
        try {
            return action.get();
        } finally {
            if (previous == null) {
                MDC.remove(LOG_FIELD);
            } else {
                MDC.put(LOG_FIELD, previous);
            }
        }
    }
}
package com.global.ct.frameinventory.frame;

import java.util.Comparator;

import com.google.protobuf.Any;
import com.google.rpc.BadRequest;
import com.google.rpc.ErrorInfo;
import io.grpc.Status;
import io.grpc.StatusException;
import io.grpc.protobuf.StatusProto;
import jakarta.validation.ConstraintViolationException;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.grpc.server.exception.GrpcExceptionHandler;
import org.springframework.stereotype.Component;

@Component
class FrameGrpcExceptionHandler implements GrpcExceptionHandler {
    private static final Logger LOGGER = LoggerFactory.getLogger(FrameGrpcExceptionHandler.class);

    @Override
    public StatusException handleException(Throwable exception) {
        if (exception instanceof FrameProblem problem) {
            return frameProblem(problem);
        }
        if (exception instanceof ConstraintViolationException invalid) {
            var errors = BadRequest.newBuilder();
            invalid.getConstraintViolations().stream()
                .map(violation -> fieldError(violation.getPropertyPath().toString(), violation.getMessage()))
                .sorted(Comparator.comparing((BadRequest.FieldViolation violation) -> violation.getField())
                    .thenComparing(BadRequest.FieldViolation::getDescription))
                .forEach(errors::addFieldViolations);
            return invalidRequest(errors.build());
        }
        if (exception instanceof InvalidField invalid) {
            return invalidRequest(BadRequest.newBuilder()
                .addFieldViolations(fieldError(invalid.field, invalid.getMessage()))
                .build());
        }
        return null;
    }

    private static StatusException frameProblem(FrameProblem problem) {
        Status.Code code = switch (problem.code()) {
            case FRAME_NOT_FOUND -> Status.Code.NOT_FOUND;
            case FRAME_ID_RESERVED -> Status.Code.ALREADY_EXISTS;
            case STALE_FRAME_VERSION -> Status.Code.ABORTED;
        };
        var log = LOGGER.atDebug()
            .addKeyValue("grpcStatus", code.name())
            .addKeyValue("reason", problem.code().name());
        var error = ErrorInfo.newBuilder()
            .setDomain("frameinventory.v1")
            .setReason(problem.code().name());
        if (problem.currentVersionId() != null) {
            error.putMetadata("currentVersionId", problem.currentVersionId().toString());
            log.addKeyValue("currentVersionId", problem.currentVersionId());
        }
        log.log("frame.client_error");
        return status(code, problem.getMessage(), Any.pack(error.build()));
    }

    private static StatusException invalidRequest(BadRequest errors) {
        LOGGER.atDebug()
            .addKeyValue("grpcStatus", Status.Code.INVALID_ARGUMENT.name())
            .addKeyValue("reason", "INVALID_REQUEST")
            .addKeyValue("fieldErrorCount", errors.getFieldViolationsCount())
            .log("frame.client_error");
        return status(Status.Code.INVALID_ARGUMENT, "One or more request values are invalid.", Any.pack(errors));
    }

    private static StatusException status(Status.Code code, String message, Any details) {
        return StatusProto.toStatusException(com.google.rpc.Status.newBuilder()
            .setCode(code.value())
            .setMessage(message)
            .addDetails(details)
            .build());
    }

    private static BadRequest.FieldViolation fieldError(String field, String message) {
        return BadRequest.FieldViolation.newBuilder().setField(field).setDescription(message).build();
    }

    static final class InvalidField extends RuntimeException {
        private final String field;

        InvalidField(String field, String message) {
            super(message);
            this.field = field;
        }
    }
}
package com.global.ct.frameinventory.frame;

import com.google.protobuf.Empty;
import io.grpc.stub.StreamObserver;
import jakarta.validation.ConstraintViolationException;
import jakarta.validation.Valid;
import jakarta.validation.Validator;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.spi.LoggingEventBuilder;
import org.springframework.stereotype.Service;

import com.global.ct.frameinventory.grpc.v1.CreateFrameRequest;
import com.global.ct.frameinventory.grpc.v1.DeleteFrameRequest;
import com.global.ct.frameinventory.grpc.v1.Frame;
import com.global.ct.frameinventory.grpc.v1.FrameManagementGrpc;
import com.global.ct.frameinventory.grpc.v1.GetFrameHistoryRequest;
import com.global.ct.frameinventory.grpc.v1.GetFrameHistoryResponse;
import com.global.ct.frameinventory.grpc.v1.GetFrameRequest;
import com.global.ct.frameinventory.grpc.v1.ListFramesRequest;
import com.global.ct.frameinventory.grpc.v1.ListFramesResponse;
import com.global.ct.frameinventory.grpc.v1.UpdateFrameRequest;

@Service
class FrameGrpcService extends FrameManagementGrpc.FrameManagementImplBase {
    private static final Logger LOGGER = LoggerFactory.getLogger(FrameGrpcService.class);

    private final FrameService frames;
    private final Validator validator;

    FrameGrpcService(FrameService frames, Validator validator) {
        this.frames = frames;
        this.validator = validator;
    }

    @Override
    public void listFrames(ListFramesRequest request, StreamObserver<ListFramesResponse> response) {
        var query = new PageQuery(request.getPage(), request.hasSize() ? request.getSize() : 25);
        LOGGER.atDebug()
            .addKeyValue("rpc", "ListFrames")
            .addKeyValue("page", query.page())
            .addKeyValue("size", query.size())
            .log("frame.rpc_received");
        validate(query);
        var page = frames.list(query.page(), query.size());
        var items = page.items().stream().map(FrameProtoMapper::toProto).toList();
        reply(response, ListFramesResponse.newBuilder()
            .addAllItems(items)
            .setPage(page.page())
            .setSize(page.size())
            .setHasNext(page.hasNext())
            .build());
    }

    @Override
    public void getFrame(GetFrameRequest request, StreamObserver<Frame> response) {
        requestLog("GetFrame", request.getFrameId()).log("frame.rpc_received");
        validate(new FrameId(request.getFrameId()));
        reply(response, FrameProtoMapper.toProto(frames.detail(request.getFrameId())));
    }

    @Override
    public void getFrameHistory(GetFrameHistoryRequest request, StreamObserver<GetFrameHistoryResponse> response) {
        requestLog("GetFrameHistory", request.getFrameId()).log("frame.rpc_received");
        validate(new FrameId(request.getFrameId()));
        var versions = frames.history(request.getFrameId()).stream().map(FrameProtoMapper::toProto).toList();
        reply(response, GetFrameHistoryResponse.newBuilder().addAllVersions(versions).build());
    }

    @Override
    public void createFrame(CreateFrameRequest request, StreamObserver<Frame> response) {
        requestLog("CreateFrame", request.getFrameId())
            .addKeyValue("hasAttributes", request.hasAttributes())
            .log("frame.rpc_received");
        var command = new Create(
            request.getFrameId(),
            request.hasAttributes() ? FrameProtoMapper.toAttributes(request.getAttributes()) : null
        );
        validate(command);
        reply(response, FrameProtoMapper.toProto(frames.create(command.frameId(), command.attributes())));
    }

    @Override
    public void updateFrame(UpdateFrameRequest request, StreamObserver<Frame> response) {
        requestLog("UpdateFrame", request.getFrameId())
            .addKeyValue("expectedVersionId", request.getExpectedVersionId())
            .addKeyValue("hasAttributes", request.hasAttributes())
            .log("frame.rpc_received");
        var command = new Update(
            request.getFrameId(),
            request.getExpectedVersionId(),
            request.hasAttributes() ? FrameProtoMapper.toAttributes(request.getAttributes()) : null
        );
        validate(command);
        reply(response, FrameProtoMapper.toProto(frames.edit(
            command.frameId(), command.expectedVersionId(), command.attributes()
        )));
    }

    @Override
    public void deleteFrame(DeleteFrameRequest request, StreamObserver<Empty> response) {
        var command = new Delete(
            request.getFrameId(), request.hasExpectedVersionId() ? request.getExpectedVersionId() : null
        );
        requestLog("DeleteFrame", command.frameId())
            .addKeyValue("expectedVersionId", command.expectedVersionId())
            .log("frame.rpc_received");
        validate(command);
        frames.delete(command.frameId(), command.expectedVersionId());
        reply(response, Empty.getDefaultInstance());
    }

    private static LoggingEventBuilder requestLog(String rpc, String frameId) {
        return LOGGER.atDebug()
            .addKeyValue("rpc", rpc)
            .addKeyValue("frameId", frameId.length() <= 128 ? frameId : "<oversize>");
    }

    private void validate(Object request) {
        var violations = validator.validate(request);
        if (!violations.isEmpty()) {
            throw new ConstraintViolationException(violations);
        }
    }

    private static <T> void reply(StreamObserver<T> response, T value) {
        response.onNext(value);
        response.onCompleted();
    }

    private record PageQuery(@PositiveOrZero int page, @Positive @Max(50) int size) {}

    private record FrameId(@NotBlank String frameId) {}

    private record Create(
        @NotBlank @Size(max = 128) @Pattern(regexp = "[^\\p{Cntrl}]+") String frameId,
        @NotNull @Valid FrameAttributes attributes
    ) {}

    private record Update(
        @NotBlank String frameId,
        @Positive long expectedVersionId,
        @NotNull @Valid FrameAttributes attributes
    ) {}

    private record Delete(@NotBlank String frameId, @Positive Long expectedVersionId) {}
}
import './sentry'
import { startStandaloneServer } from '@apollo/server/standalone'
import { credentials, loadPackageDefinition } from '@grpc/grpc-js'
import { loadSync } from '@grpc/proto-loader'
import { PrometheusExporter } from '@opentelemetry/exporter-prometheus'
import { MeterProvider } from '@opentelemetry/sdk-metrics'
import { randomUUID } from 'node:crypto'
import { resolve } from 'node:path'
import type { ProtoGrpcType } from './generated/frames'
import { logger } from './logger'
import { createMetricsPlugin } from './metrics'
import { createServer } from './server'

async function main() {
  const protoPath = resolve(__dirname, 'proto/frames.proto')
  const definition = loadSync(protoPath, { longs: String, defaults: true })
  const proto = loadPackageDefinition(definition) as unknown as ProtoGrpcType
  const endpoint =
    process.env.FRAME_GRPC_ENDPOINT ??
    process.env.FRAME_GRPC_TARGET ??
    'localhost:9090'
  const client = new proto.frameinventory.v1.FrameManagement(
    endpoint,
    credentials.createInsecure(),
  )

  const exporter = new PrometheusExporter({
    host: process.env.OTEL_EXPORTER_PROMETHEUS_HOST ?? '127.0.0.1',
    port: 9465,
    preventServerStart: true,
  })
  const meterProvider = new MeterProvider({ readers: [exporter] })

  try {
    const server = createServer(client)
    server.addPlugin(
      createMetricsPlugin(meterProvider.getMeter('frame-inventory-bff')),
    )
    server.addPlugin({
      async serverWillStart() {
        await exporter.startServer()
        return {
          async serverWillStop() {
            await meterProvider.shutdown()
          },
        }
      },
    })
    const { url } = await startStandaloneServer(server, {
      context: async () => ({ correlationId: randomUUID() }),
      listen: { port: 4000 },
    })
    logger.info({ url }, 'Frame Inventory GraphQL API available')
  } catch (error) {
    client.close()
    await meterProvider.shutdown()
    throw error
  }
}

main().catch((error: unknown) => {
  logger.error({ err: error }, 'Could not start the Frame Inventory BFF')
  process.exitCode = 1
})
